mapper.select:
select professional_role_id, role_code, role_name, role_description, system_flag, status, sort_order, create_by, create_time, update_by, update_time from pm_professional_role
and role_code like concat('%', #{roleCode}, '%') and role_name like concat('%', #{roleName}, '%') and status = #{status}
order by system_flag desc, sort_order, professional_role_id
